<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api } from '../api'
const props=defineProps<{skill:{id:string;name:string;builtin:boolean;sourceUrl:string}}>()
const emit=defineEmits<{close:[];updated:[];preview:[value:Record<string,unknown>]}>()
interface Dependency {kind:string;requiredMajor:number;required:string;current:string;status:string;managed:boolean}
interface Check {status:string;dependencies:Dependency[];note:string}
const check=ref<Check|null>(null),busy=ref(false),error=ref(''),notice=ref(''),versions=ref<Array<{id:string;source_url:string;created_at:string}>>([]),restore=ref('')
function versionTime(value:string){const date=new Date(value.replace(' ','T').replace(/(\.\d{3})\d+/,'$1').replace(/([+-]\d{2})$/,'$1:00'));return Number.isNaN(date.getTime())?value:date.toLocaleString('zh-CN')}
const raw=()=>props.skill.id.replace('user:','')
async function refresh(){busy.value=true;error.value='';try{check.value=await api.get<Check>('/api/skills/'+encodeURIComponent(props.skill.id)+'/dependencies');if(!props.skill.builtin)versions.value=(await api.get<{versions:typeof versions.value}>(`/api/skills/${raw()}/versions`)).versions}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function install(row:Dependency){busy.value=true;error.value='';notice.value='正在从Node.js官方下载并校验安装包，请等待…';try{const result=await api.post<{version:string}>('/api/runtimes/node',{major:row.requiredMajor>22?24:22});notice.value='私有运行时 '+result.version+' 已安装，系统Node和全局PATH未修改。';await refresh()}catch(e){error.value=(e as Error).message;notice.value=''}finally{busy.value=false}}
async function update(){busy.value=true;try{const result=await api.post<Record<string,unknown>>(`/api/skills/${raw()}/preview-update`);emit('preview',result)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function rollback(){busy.value=true;try{await api.post(`/api/skills/${raw()}/rollback`,{versionId:restore.value});restore.value='';notice.value='已恢复所选技能版本。';emit('updated');await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(refresh)
</script>
<template><div class="dependency-overlay" @click.self="!busy&&emit('close')"><section class="dependency-dialog"><header><div><span class="eyebrow">SKILL ENVIRONMENT</span><h2>{{ skill.name }}</h2></div><button class="btn" :disabled="busy" @click="emit('close')">关闭</button></header><p>技能已安装，依赖和业务流程运行结果分别检查。</p><p v-if="!check">正在检查本机环境…</p><template v-else><span class="badge" :class="check.status==='ready'?'ok':'wait'">{{ check.status==='ready'?'运行时检查通过':check.status==='unknown'?'依赖声明不完整':'需要配置依赖' }}</span><div v-for="row in check.dependencies" :key="row.kind" class="dependency-row"><div><strong>{{ ({node:'Node.js',python:'Python',browser:'Chrome / Edge'} as Record<string,string>)[row.kind] || row.kind }}</strong><small>要求 {{ row.required }}</small><p>{{ row.current }} <span v-if="row.managed">· Agent私有</span></p></div><span>{{ row.status==='ready'?'就绪':row.status==='missing'?'未安装':'版本不兼容' }}</span><button v-if="row.kind==='node'&&row.status!=='ready'&&row.requiredMajor<=24" class="btn btn-primary btn-sm install-node" :disabled="busy" @click="install(row)">安装私有 Node {{ row.requiredMajor>22?24:22 }}</button></div><p class="dim small">{{ check.note }}</p></template>
 <div class="dependency-actions"><button class="btn" :disabled="busy" @click="refresh">重新检查</button><button v-if="!skill.builtin&&skill.sourceUrl" class="btn" :disabled="busy" @click="update">检查技能更新</button></div>
 <h3 v-if="versions.length">历史版本</h3><div v-for="version in versions" :key="version.id" class="dependency-row"><span>{{ versionTime(version.created_at) }}<small>{{ version.source_url.match(/\/tree\/([a-f0-9]{12})/)?.[1] || '手动保存' }}</small></span><button class="btn btn-sm" :disabled="busy" @click="restore=version.id">恢复此版本</button></div><div v-if="restore"><p>将恢复所选版本的技能指导，当前版本也会保留到历史记录。</p><button class="btn btn-danger btn-sm" :disabled="busy" @click="rollback">确认恢复</button><button class="btn btn-sm" @click="restore=''">取消</button></div>
 <p v-if="notice" class="small">{{ notice }}</p><p v-if="error" class="dependency-error">{{ error }}</p></section></div></template>
<style scoped>
.dependency-overlay{position:fixed;inset:0;z-index:42;background:#18251b55;backdrop-filter:blur(4px);padding:24px;display:grid;place-items:center}.dependency-dialog{background:var(--ink-2);border:1px solid var(--line);border-radius:16px;padding:28px;width:min(760px,100%);max-height:90vh;overflow:auto;color:var(--txt-1);font-size:12px}.dependency-dialog header{display:flex;align-items:center;justify-content:space-between}.dependency-dialog h2{font-size:21px}.dependency-dialog p{line-height:1.8;overflow-wrap:anywhere}.dependency-row{display:flex;align-items:center;gap:14px;padding:15px 0;border-bottom:1px solid var(--line)}.dependency-row>div{flex:1}.dependency-row small{display:block;color:var(--txt-3);font-size:10px;margin-top:5px}.dependency-row p{font-size:11px;color:var(--txt-2);max-width:440px}.dependency-actions{display:flex;gap:9px;margin-top:20px}.dependency-error{color:var(--red)}
</style>
